CREATE TRIGGER ros_messages_ad AFTER DELETE ON ros_messages BEGIN
  DELETE FROM ros_messages_fts WHERE id = old.id;
END

CREATE TRIGGER ros_messages_au AFTER UPDATE OF content, tool_result, id ON ros_messages BEGIN
  DELETE FROM ros_messages_fts WHERE id = old.id;
  INSERT INTO ros_messages_fts(id, content, tool_result)
  VALUES (new.id, new.content, coalesce(new.tool_result, ''));
END

CREATE TRIGGER ros_summaries_ai AFTER INSERT ON ros_summaries BEGIN
  INSERT INTO ros_summaries_fts(id, content) VALUES (new.id, new.content);
END

CREATE TRIGGER ros_summaries_ad AFTER DELETE ON ros_summaries BEGIN
  DELETE FROM ros_summaries_fts WHERE id = old.id;
END

CREATE TRIGGER ros_summaries_au AFTER UPDATE OF content, id ON ros_summaries BEGIN
  DELETE FROM ros_summaries_fts WHERE id = old.id;
  INSERT INTO ros_summaries_fts(id, content) VALUES (new.id, new.content);
END

CREATE TRIGGER ros_wiki_topics_ai AFTER INSERT ON ros_wiki_topics BEGIN
    INSERT INTO ros_wiki_topics_fts (slug, search_text) VALUES (new.slug, new.search_text);
END

CREATE TRIGGER ros_wiki_topics_ad AFTER DELETE ON ros_wiki_topics BEGIN
    DELETE FROM ros_wiki_topics_fts WHERE slug = old.slug;
END

CREATE TRIGGER ros_wiki_topics_au AFTER UPDATE OF search_text ON ros_wiki_topics BEGIN
    DELETE FROM ros_wiki_topics_fts WHERE slug = old.slug;
    INSERT INTO ros_wiki_topics_fts (slug, search_text) VALUES (new.slug, new.search_text);
END
